// Category C — no headless keypad exists, so it is assembled from React Aria: Toolbar gives one tab
// stop with roving focus, and Button gives press handling. Toolbar moves focus LINEARLY: Left/Right
// step through the twelve slots in reading order and wrap rows, and Up/Down do nothing. That still
// reaches every key from a kiosk's physical arrow keys (the Korean kiosk accessibility notice,
// 과학기술정보통신부고시 제2025-55호), and hand-rolling ±3 grid navigation would reimplement behaviour
// this system borrows. The key set follows the shipped point-of-sale keypads it was drawn from: digits only, `00` for amounts, an empty slot otherwise, and delete always in
// the bottom-right corner. Anything that is not a digit (a running-total `+`, a submit button) belongs
// beside the keypad, not in it.
//
// The grid stays left-to-right in every locale: a phone or POS keypad keeps 1 at the top left under
// RTL too (the ITU-T E.161 layout is fixed). React Aria reverses ArrowLeft/ArrowRight from the
// locale's direction, so under an RTL locale the toolbar is scoped in an LTR I18nProvider; `dir="ltr"`
// alone would leave the arrows moving against the visual order.
import {
  Button as AriaButton,
  I18nProvider,
  Toolbar as AriaToolbar,
  useLocale,
} from "react-aria-components";
import type { ToolbarProps as AriaToolbarProps } from "react-aria-components";
import { Backspace } from "./icons";
import { useState } from "react";
import type { Ref } from "react";
import { roleSize, type ControlSize } from "./controlSize";
import "./NumericKeypad.css";

type NumericKeypadSize = ControlSize;

export interface NumericKeypadBaseProps
  extends Omit<
    AriaToolbarProps,
    | "className"
    | "children"
    | "orientation"
    | "aria-label"
    | "aria-labelledby"
    | "onChange"
    | "defaultValue"
  > {
  /**
   * Size axis: key height, digit type role and delete glyph.
   *
   * @default "medium"
   */
  size?: NumericKeypadSize;
  /**
   * What is being entered. `amount` puts a `00` key in the bottom-left slot and never lets the value
   * start with a zero, normalising a stored "007" to "71" on the next press; `digits` leaves that slot
   * empty and keeps leading zeros (a phone number, a PIN, a quantity).
   *
   * @default "digits"
   */
  purpose?: "amount" | "digits";
  /** Controlled value. Digits only: the keypad appends to it as a string and does not validate it. */
  value?: string;
  /** Initial value when uncontrolled. Digits only, as for `value`. */
  defaultValue?: string;
  /** Called with the next value after every key press that changes it. */
  onChange?: (value: string) => void;
  /** Maximum number of digits. A key that would pass it is ignored whole (`00` is not half-entered);
   *  a value already longer than this is never shortened. */
  maxLength?: number;
  /** Accessible name of the delete key, which shows only a glyph (WCAG 4.1.2). */
  deleteLabel: string;
  /** Disables every key. */
  isDisabled?: boolean;
  /** Additional class. sd-numeric-keypad is always retained. */
  className?: string;
  /** Passed to the root toolbar DOM element. */
  ref?: Ref<HTMLDivElement>;
}

/**
 * A keypad has no visible label of its own, so its `role="toolbar"` needs an accessible name:
 * `aria-label` or `aria-labelledby` is required at the type level, as on Toolbar.
 */
export type NumericKeypadProps =
  | (NumericKeypadBaseProps & { "aria-label": string })
  | (NumericKeypadBaseProps & { "aria-labelledby": string });

const DIGITS = ["1", "2", "3", "4", "5", "6", "7", "8", "9"] as const;

export function NumericKeypad({
  size = "medium",
  purpose = "digits",
  value,
  defaultValue = "",
  onChange,
  maxLength,
  deleteLabel,
  isDisabled,
  className,
  ref,
  ...props
}: NumericKeypadProps) {
  const [uncontrolled, setUncontrolled] = useState(defaultValue);
  const current = value ?? uncontrolled;

  const commit = (next: string) => {
    if (next === current) return;
    if (value === undefined) setUncontrolled(next);
    onChange?.(next);
  };
  const append = (key: string) => {
    let next = current + key;
    if (purpose === "amount") next = next.replace(/^0+/, "");
    // Ignore the whole key rather than cut it: slicing turned "12345678" + `00` into ×10, not ×100.
    if (maxLength !== undefined && next.length > maxLength && next.length > current.length) return;
    commit(next);
  };

  const keyClass = `sd-numeric-keypad__key sd-type-title-${roleSize(size)}`;
  const digitKey = (key: string) => (
    <AriaButton
      key={key}
      className={keyClass}
      data-size={size}
      isDisabled={isDisabled}
      onPress={() => append(key)}
    >
      {key}
    </AriaButton>
  );

  const { direction } = useLocale();
  const toolbar = (
    <AriaToolbar
      {...props}
      ref={ref}
      orientation="horizontal"
      dir="ltr"
      data-size={size}
      className={className ? `sd-numeric-keypad ${className}` : "sd-numeric-keypad"}
    >
      {DIGITS.map(digitKey)}
      {purpose === "amount" ? (
        digitKey("00")
      ) : (
        <span className="sd-numeric-keypad__slot" aria-hidden="true" />
      )}
      {digitKey("0")}
      <AriaButton
        className="sd-numeric-keypad__key"
        data-size={size}
        data-key="delete"
        aria-label={deleteLabel}
        isDisabled={isDisabled}
        onPress={() => commit(current.slice(0, -1))}
      >
        <Backspace aria-hidden size="1em" />
      </AriaButton>
    </AriaToolbar>
  );
  return direction === "rtl" ? <I18nProvider locale="en-US">{toolbar}</I18nProvider> : toolbar;
}

/* Three equal columns, four rows. Keys fill their cell, so the keypad takes the width its container
   gives it and each key keeps at least the control height of its size. */
.sd-numeric-keypad {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--sd-numeric-keypad-gap);
}

.sd-numeric-keypad__key {
  --sd-numeric-keypad-key-radius-current: var(--sd-numeric-keypad-key-radius-medium);
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--sd-numeric-keypad-key-background);
  color: var(--sd-numeric-keypad-key-foreground);
  /* explicitly borderless: the element is a native <button>, so omitting `border` would let the
     UA-default button border show through. */
  border: none;
  border-radius: var(--sd-numeric-keypad-key-radius-current);
  corner-shape: superellipse(var(--sd-radius-curve));
  font-variant-numeric: tabular-nums;
  cursor: pointer;
  user-select: none;
  /* a keypad is tapped in quick runs; this stops a double tap from zooming instead of entering */
  touch-action: manipulation;
  outline: none;
}

.sd-numeric-keypad__key[data-size="x-small"] {
  --sd-numeric-keypad-key-radius-current: var(--sd-numeric-keypad-key-radius-x-small);
  min-height: var(--sd-numeric-keypad-key-min-height-x-small);
}
.sd-numeric-keypad__key[data-size="small"] {
  --sd-numeric-keypad-key-radius-current: var(--sd-numeric-keypad-key-radius-small);
  min-height: var(--sd-numeric-keypad-key-min-height-small);
}
.sd-numeric-keypad__key[data-size="medium"] {
  --sd-numeric-keypad-key-radius-current: var(--sd-numeric-keypad-key-radius-medium);
  min-height: var(--sd-numeric-keypad-key-min-height-medium);
}
.sd-numeric-keypad__key[data-size="large"] {
  --sd-numeric-keypad-key-radius-current: var(--sd-numeric-keypad-key-radius-large);
  min-height: var(--sd-numeric-keypad-key-min-height-large);
}
.sd-numeric-keypad__key[data-size="x-large"] {
  --sd-numeric-keypad-key-radius-current: var(--sd-numeric-keypad-key-radius-x-large);
  min-height: var(--sd-numeric-keypad-key-min-height-x-large);
}

/* the delete glyph sits on the icon scale; it carries no type-role class, so this is its only
   font-size (contract §7: an icon glyph keeps its font-size Cmp token). */
.sd-numeric-keypad__key[data-key="delete"][data-size="x-small"] {
  font-size: var(--sd-numeric-keypad-key-icon-size-x-small);
}
.sd-numeric-keypad__key[data-key="delete"][data-size="small"] {
  font-size: var(--sd-numeric-keypad-key-icon-size-small);
}
.sd-numeric-keypad__key[data-key="delete"][data-size="medium"] {
  font-size: var(--sd-numeric-keypad-key-icon-size-medium);
}
.sd-numeric-keypad__key[data-key="delete"][data-size="large"] {
  font-size: var(--sd-numeric-keypad-key-icon-size-large);
}
.sd-numeric-keypad__key[data-key="delete"][data-size="x-large"] {
  font-size: var(--sd-numeric-keypad-key-icon-size-x-large);
}

/* hover/pressed via the global state-layer overlay (ADR-0009). No press scale: contract §6 rule 7
   keeps `state.pressed-scale` to Button and ToggleButtonGroup. */
.sd-numeric-keypad__key::after {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: inherit;
  corner-shape: inherit;
  background: transparent;
  pointer-events: none;
  transition: background-color var(--sd-duration-moderate) var(--sd-easing-standard);
}
.sd-numeric-keypad__key[data-hovered]::after {
  background: var(--sd-state-hover);
}
.sd-numeric-keypad__key[data-pressed]::after {
  background: var(--sd-state-pressed);
}
.sd-numeric-keypad__key[data-focus-visible] {
  box-shadow: 0 0 0 var(--sd-state-focus-ring-width) color-mix(in srgb, var(--sd-state-focus-ring) calc(var(--sd-state-focus-ring-opacity) * 100%), transparent);
  outline: var(--sd-state-focus-ring-width) solid transparent;
}
.sd-numeric-keypad__key[data-disabled] {
  opacity: var(--sd-state-disabled);
  cursor: not-allowed;
}
